/**
 * Regenerate expected.json from static/js/backtester.js — the SOURCE OF
 * TRUTH for the Full-Simulation semantics (carrac/backtest_sim.py
 * is a port of it, not the other way around, so — unlike
 * tests/golden/formula/regenerate.py, which regenerates from the Python
 * side — this golden is generated by running the real JS engine with its
 * real FormulaParser/TALib dependencies loaded, via Node's `vm` module).
 *
 * Every case is run with the faithful/JS-exact fill mode: the Python side
 * must pass `gapAwareFills: false` when checking against this golden (see
 * tests/test_backtest_sim_parity.py). The gap-aware divergence
 * is Python-only and deliberately NOT covered by this cross-language golden
 * — it's covered by dedicated unit tests in tests/test_backtest_sim.py.
 *
 * Run this ONLY when intentionally changing the JS engine (or adding new
 * pinned cases). In normal CI, tests/test_backtest_sim_parity.py verifies
 * the Python port still matches this pinned expected.json.
 *
 * Run: node tests/golden/backtest_sim/regenerate.mjs
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import vm from 'node:vm';

const __dirname = dirname(fileURLToPath(import.meta.url));
const ROOT = join(__dirname, '..', '..', '..');

function loadScript(relPath, sandbox) {
    const code = readFileSync(join(ROOT, relPath), 'utf8');
    vm.runInContext(code, sandbox, { filename: relPath });
}

function makeSandbox() {
    const sandbox = { console, setTimeout, clearTimeout, Math };
    sandbox.window = sandbox;
    vm.createContext(sandbox);
    return sandbox;
}

function loadBacktester() {
    const sandbox = makeSandbox();
    loadScript('static/js/ta-lib.js', sandbox);
    loadScript('static/js/formula-parser.js', sandbox);
    loadScript('static/js/backtester.js', sandbox);
    return sandbox.window.Backtester;
}

function round6(v) {
    if (v === null || v === undefined) return null;
    if (typeof v !== 'number' || Number.isNaN(v)) return null;
    if (!Number.isFinite(v)) return v > 0 ? 'Infinity' : '-Infinity';
    return Math.round(v * 1e6) / 1e6;
}

function sanitizeTrade(t) {
    return {
        entryBar: t.entryBar,
        exitBar: t.exitBar,
        entryPrice: round6(t.entryPrice),
        exitPrice: round6(t.exitPrice),
        direction: t.direction,
        pnl: round6(t.pnl),
        pnlPercent: round6(t.pnlPercent),
        bars: t.bars,
        fundingCost: round6(t.fundingCost),
        exitReason: t.exitReason,
        regime: t.regime,
    };
}

function sanitizeStatsBlock(s) {
    if (!s) return null;
    const out = {};
    for (const k of Object.keys(s)) out[k] = round6(s[k]);
    return out;
}

function sanitizeStatsRegime(sr) {
    if (!sr) return null;
    return {
        favorable: sanitizeStatsBlock(sr.favorable),
        unfavorable: sanitizeStatsBlock(sr.unfavorable),
        unknown: sanitizeStatsBlock(sr.unknown),
    };
}

function main() {
    const fixtures = JSON.parse(readFileSync(join(__dirname, 'fixtures.json'), 'utf8'));
    const ohlcvByName = {};
    for (const f of fixtures.ohlcv_fixtures) ohlcvByName[f.name] = f;

    const BT = loadBacktester();
    const expected = { results: [] };

    for (const c of fixtures.cases) {
        const ohlcv = ohlcvByName[c.fixture];
        // gapAwareFills is a Python-only key the JS engine doesn't know about;
        // harmless to pass through (JS just ignores unknown config keys).
        const result = BT.run(c.config, ohlcv);
        expected.results.push({
            id: c.id,
            fixture: c.fixture,
            error: result.error,
            trades: result.error ? [] : result.trades.map(sanitizeTrade),
            equity: result.error ? [] : result.equity.map(round6),
            stats: result.error ? null : sanitizeStatsBlock(result.stats),
            statsRegime: result.error ? null : sanitizeStatsRegime(result.statsRegime),
        });
    }

    writeFileSync(join(__dirname, 'expected.json'), JSON.stringify(expected, null, 2));
    console.log(`Regenerated expected.json — ${expected.results.length} cases`);
}

main();
